/// Check whether an error is an EOF (Ctrl+D) condition.
fn is_eof(err: &BivvyError) -> bool {
    matches!(err, BivvyError::Io(e) if e.kind() == std::io::ErrorKind::UnexpectedEof)
}

/// Return a fallback result for a prompt that was interrupted by EOF.
fn eof_default(prompt: &Prompt) -> PromptResult {
    match &prompt.prompt_type {
        PromptType::Confirm => {
            let val = prompt
                .default
                .as_ref()
                .map(|s| s.to_lowercase() == "true" || s == "y" || s == "yes")
                .unwrap_or(false);
            PromptResult::Bool(val)
        }
        PromptType::Input => {
            PromptResult::String(prompt.default.clone().unwrap_or_default())
        }
        PromptType::Select { options } => {
            let val = prompt
                .default
                .clone()
                .or_else(|| options.first().map(|o| o.value.clone()))
                .unwrap_or_default();
            PromptResult::String(val)
        }
        PromptType::MultiSelect { .. } => {
            let vals: Vec<String> = prompt
                .default
                .as_deref()
                .map(|d| d.split(',').map(|s| s.trim().to_string()).collect())
                .unwrap_or_default();
            PromptResult::Strings(vals)
        }
    }
}

