        assert!(!is_eof(&err));
    }

    #[test]
    fn eof_default_confirm_uses_default_true() {
        let prompt = make_prompt("q", PromptType::Confirm, Some("true"));
        match eof_default(&prompt) {
            PromptResult::Bool(v) => assert!(v),
            _ => panic!("expected Bool"),
        }
    }

    #[test]
    fn eof_default_confirm_uses_default_false() {
        let prompt = make_prompt("q", PromptType::Confirm, Some("no"));
        match eof_default(&prompt) {
            PromptResult::Bool(v) => assert!(!v),
            _ => panic!("expected Bool"),
        }
    }

    #[test]
    fn eof_default_confirm_no_default_returns_false() {
        let prompt = make_prompt("q", PromptType::Confirm, None);
        match eof_default(&prompt) {
            PromptResult::Bool(v) => assert!(!v),
            _ => panic!("expected Bool"),
        }
    }

    #[test]
    fn eof_default_input_uses_default() {
        let prompt = make_prompt("q", PromptType::Input, Some("hello"));
        assert_eq!(eof_default(&prompt).as_string(), "hello");
    }

