    fn eof_default_input_no_default_returns_empty() {
        let prompt = make_prompt("q", PromptType::Input, None);
        assert_eq!(eof_default(&prompt).as_string(), "");
    }

    #[test]
    fn eof_default_select_uses_default() {
        let options = vec![
            PromptOption {
                label: "A".to_string(),
                value: "a".to_string(),
            },
            PromptOption {
                label: "B".to_string(),
                value: "b".to_string(),
            },
        ];
        let prompt = make_prompt(
            "q",
            PromptType::Select {
                options: options.clone(),
            },
            Some("b"),
        );
        assert_eq!(eof_default(&prompt).as_string(), "b");
    }

    #[test]
    fn eof_default_select_no_default_uses_first_option() {
        let options = vec![
            PromptOption {
                label: "X".to_string(),
                value: "x".to_string(),
            },
            PromptOption {
                label: "Y".to_string(),
                value: "y".to_string(),
            },
        ];
        let prompt = make_prompt(
            "q",
            PromptType::Select {
                options: options.clone(),
            },
            None,
        );
        assert_eq!(eof_default(&prompt).as_string(), "x");
    }

    #[test]
    fn eof_default_multiselect_uses_default() {
        let options = vec![
            PromptOption {
                label: "A".to_string(),
                value: "a".to_string(),
            },
            PromptOption {
                label: "B".to_string(),
                value: "b".to_string(),
            },
        ];
        let prompt = make_prompt(
            "q",
            PromptType::MultiSelect {
                options: options.clone(),
            },
            Some("a,b"),
        );
        match eof_default(&prompt) {
            PromptResult::Strings(v) => assert_eq!(v, vec!["a", "b"]),
            _ => panic!("expected Strings"),
        }
    }

    #[test]
    fn eof_default_multiselect_no_default_returns_empty() {
        let options = vec![PromptOption {
            label: "A".to_string(),
            value: "a".to_string(),
        }];
        let prompt = make_prompt(
            "q",
            PromptType::MultiSelect {
                options: options.clone(),
            },
            None,
        );
        match eof_default(&prompt) {
            PromptResult::Strings(v) => assert!(v.is_empty()),
            _ => panic!("expected Strings"),
        }
    }

    #[test]
    fn prompt_user_returns_default_on_eof() {
        // On non-TTY, dialoguer returns NotConnected, not UnexpectedEof.
        // Test the EOF fallback logic directly via prompt_user by
        // verifying that a prompt with an env-var override still works
        // (ensuring prompt_user doesn't break existing paths).
        let prompt = make_prompt("EOF_TEST_KEY_XYZZY", PromptType::Input, Some("fallback"));
        std::env::set_var("EOF_TEST_KEY_XYZZY", "override");
        let result = prompt_user(&prompt, &Term::stdout());
        std::env::remove_var("EOF_TEST_KEY_XYZZY");
        assert_eq!(result.unwrap().as_string(), "override");
    }
}

